from typing import Any, Dict

def load_config_with_defaults(config_path: str, defaults: Dict[str, Any]) -> Dict[str, Any]:
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
        if not isinstance(config, dict):
            raise ValueError(f'Expected dict in config file, got {type(config).__name__}')
        return _deep_merge(defaults, config)
    except FileNotFoundError:
        return defaults
    except json.JSONDecodeError as e:
        raise ValueError(f'Invalid JSON in {config_path}: {str(e)}')

def _deep_merge(a: Dict[str, Any], b: Dict[str, Any]) -> Dict[str, Any]:
    result = a.copy()
    for k, v in b.items():
        if k in a and isinstance(a[k], dict) and isinstance(v, dict):
            result[k] = _deep_merge(a[k], v)
        else:
            result[k] = v
    return result
"}

