const jwt = require('jsonwebtoken');
const { Pool } = require('pg');

const tenantDatabases = {
  'tenant1': new Pool({ connectionString: 'postgres://user:password@tenant1.db.host/db' }),
  'tenant2': new Pool({ connectionString: 'postgres://user:password@tenant2.db.host/db' })
};

function tenantMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Missing authorization token' });
  }
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    const tenantId = decoded.tenantId;
    if (!tenantDatabases[tenantId]) {
      return res.status(403).json({ error: 'Invalid tenant' });
    }
    req.db = tenantDatabases[tenantId];
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

module.exports = tenantMiddleware;

const request = require('supertest');
const app = require('../app');
const jwt = require('jsonwebtoken');

describe('Tenant Isolation Middleware', () => {
  const tenant1Token = jwt.sign({ tenantId: 'tenant1' }, process.env.JWT_SECRET);
  const tenant2Token = jwt.sign({ tenantId: 'tenant2' }, process.env.JWT_SECRET);

  it('should allow tenant1 to access their data', async () => {
    const res = await request(app)
      .get('/products')
      .set('Authorization', `Bearer ${tenant1Token}`);
    expect(res.status).toBe(200);
  });

  it('should reject requests with missing tokens', async () => {
    const res = await request(app).get('/products');
    expect(res.status).toBe(401);
  });

  it('should reject requests with invalid tokens', async () => {
    const res = await request(app)
      .get('/products')
      .set('Authorization', 'Bearer invalidtoken');
    expect(res.status).toBe(401);
  });

  it('should prevent tenant1 from accessing tenant2\'s data', async () => {
    const res = await request(app)
      .get('/products')
      .set('Authorization', `Bearer ${tenant1Token}`);
    expect(res.body).not.toContainEqual(expect.objectContaining({ id: 'tenant2_product' }));
  });
});
